@dataclass(frozen=True, slots=True)
class ReviewDecision:
    schema_version: str
    protocol_id: str
    review_decision_sha256: str | None
    review_packet_sha256: str
    candidate_id: str
    reviewer_role: ReviewerRole
    human_action: HumanReviewAction
    changed_question_ids: tuple[str, ...]
    focal_hypothesis: FocalHypothesis
    answers: tuple[ReviewAnswer, ...]
    outcome: ReviewOutcome
    non_authoritative_commentary: str | None = None

    def __post_init__(self) -> None:
        if self.schema_version != REVIEW_DECISION_SCHEMA_VERSION:
            raise ValueError("review decision schema version is unsupported")
        if self.protocol_id != HYBRID_PROTOCOL_ID:
            raise ValueError("review decision protocol identity is unsupported")
        for value, name in (
            (self.review_packet_sha256, "review_packet_sha256"),
            (self.review_decision_sha256, "review_decision_sha256"),
        ):
            if value is not None and _SHA256.fullmatch(value) is None:
                raise ValueError(f"{name} must be a lowercase SHA-256")
        if not self.candidate_id:
            raise ValueError("candidate_id must be non-empty")
        if not isinstance(self.reviewer_role, ReviewerRole):
            raise TypeError("reviewer_role is invalid")
        if not isinstance(self.human_action, HumanReviewAction):
            raise TypeError("human_action is invalid")
        if self.reviewer_role is ReviewerRole.CODEX_PROPOSAL:
            if self.human_action is not HumanReviewAction.NOT_APPLICABLE:
                raise ValueError("Codex proposals cannot claim a human action")
        elif self.human_action is HumanReviewAction.NOT_APPLICABLE:
            raise ValueError("human reviews must record a finite human action")
        _require_ordered_refs(self.changed_question_ids, "changed question IDs")
        if not set(self.changed_question_ids) <= set(_QUESTION_IDS):
            raise ValueError("changed question IDs must be drawn from Q1-Q10")
        if self.human_action is HumanReviewAction.CHANGE_ONE_OR_MORE_FINITE_ANSWERS:
            if not self.changed_question_ids:
                raise ValueError("changed finite answers must be identified")
        elif self.changed_question_ids:
            raise ValueError("changed question IDs require the finite CHANGE action")
        if tuple(item.question_id for item in self.answers) != _QUESTION_IDS:
            raise ValueError("review decisions require exactly one ordered Q1-Q10 answer")
        answer_by_id = {item.question_id: item for item in self.answers}
        if any(not answer_by_id[item].evidence_refs for item in self.changed_question_ids):
            raise ValueError("every changed answer requires evidence refs")
        expected = derive_review_outcome(self.answers)
        if self.outcome is not expected:
            raise ValueError("review outcome is inconsistent with finite answers")
        answers = {item.question_id: item.answer for item in self.answers}
        if answers["Q1"] is ReviewAnswerValue.YES and (
            self.focal_hypothesis.predicate_type is None
            or self.focal_hypothesis.protected_effect_ref is None
        ):
            raise ValueError("Q1 YES requires a predicate type and protected effect ref")
        if (
            answers["Q6"] is ReviewAnswerValue.YES
            and self.focal_hypothesis.witness_type is None
        ):
            raise ValueError("Q6 YES requires a frozen witness type")
        if (
            self.human_action is HumanReviewAction.MARK_UNRESOLVED
            and self.outcome is not ReviewOutcome.REVIEW_UNRESOLVED
        ):
            raise ValueError("MARK_UNRESOLVED requires an UNKNOWN answer")
        if self.non_authoritative_commentary is not None:
            if not isinstance(self.non_authoritative_commentary, str):
                raise TypeError("non_authoritative_commentary must be text or null")
            if _FORBIDDEN_COMMENTARY.search(self.non_authoritative_commentary):
                raise ValueError("commentary cannot contain probability or score language")


