def derive_review_outcome(answers: Iterable[ReviewAnswer]) -> ReviewOutcome:
    values = tuple(item.answer for item in answers)
    if len(values) != 10:
        raise ValueError("review outcome requires exactly ten answers")
    if ReviewAnswerValue.NO in values:
        return ReviewOutcome.REVIEW_REJECT
    if ReviewAnswerValue.UNKNOWN in values:
        return ReviewOutcome.REVIEW_UNRESOLVED
    if all(item is ReviewAnswerValue.YES for item in values):
        return ReviewOutcome.REVIEW_RETAIN
    raise ValueError("review answers must be YES, NO, or UNKNOWN")


def review_decision_payload(decision: ReviewDecision) -> dict[str, Any]:
    return _without_hash(decision, "review_decision_sha256")


def seal_review_decision(decision: ReviewDecision) -> ReviewDecision:
    if decision.review_decision_sha256 is not None:
        raise ValueError("review decision is already sealed")
    return replace(
        decision,
        review_decision_sha256=canonical_sha256(review_decision_payload(decision)),
    )


def review_decision_bytes(decision: ReviewDecision) -> bytes:
    if decision.review_decision_sha256 is None:
        raise ValueError("review_decision_sha256 is absent")
    if decision.review_decision_sha256 != canonical_sha256(
        review_decision_payload(decision)
    ):
        raise ValueError("review_decision_sha256 does not verify")
    return canonical_json_bytes(decision)


def _focal_hypothesis(value: Any) -> FocalHypothesis:
    row = _mapping(value, "focal_hypothesis")
    if set(row) != {field.name for field in fields(FocalHypothesis)}:
        raise ResultValidationError("focal hypothesis fields are invalid")
    return FocalHypothesis(
        hypothesis_id=row["hypothesis_id"],
        predicate_type=(
            None
            if row["predicate_type"] is None
            else PredicateType(row["predicate_type"])
        ),
        transition_type=(
            None
            if row["transition_type"] is None
            else TransitionType(row["transition_type"])
        ),
        witness_type=(
            None if row["witness_type"] is None else WitnessType(row["witness_type"])
        ),
        protected_effect_ref=row["protected_effect_ref"],
        evidence_refs=tuple(_list(row["evidence_refs"], "hypothesis evidence_refs")),
    )


def review_decision_from_mapping(value: Mapping[str, Any]) -> ReviewDecision:
    if set(value) != {field.name for field in fields(ReviewDecision)}:
        raise ResultValidationError("review decision fields are invalid")
    try:
        answers = tuple(
            ReviewAnswer(
                question_id=row["question_id"],
                answer=ReviewAnswerValue(row["answer"]),
                evidence_refs=tuple(
                    _list(row["evidence_refs"], "answer evidence_refs")
                ),
            )
            for row in (
                _mapping(item, "review answer")
                for item in _list(value["answers"], "answers")
            )
        )
        return ReviewDecision(
            schema_version=value["schema_version"],
            protocol_id=value["protocol_id"],
            review_decision_sha256=value["review_decision_sha256"],
            review_packet_sha256=value["review_packet_sha256"],
            candidate_id=value["candidate_id"],
            reviewer_role=ReviewerRole(value["reviewer_role"]),
            human_action=HumanReviewAction(value["human_action"]),
            changed_question_ids=tuple(
                _list(value["changed_question_ids"], "changed_question_ids")
            ),
            focal_hypothesis=_focal_hypothesis(value["focal_hypothesis"]),
            answers=answers,
            outcome=ReviewOutcome(value["outcome"]),
            non_authoritative_commentary=value["non_authoritative_commentary"],
        )
    except (KeyError, TypeError, ValueError) as error:
        if isinstance(error, ResultValidationError):
            raise
        raise ResultValidationError("review decision value is invalid") from error


